// src/components/SocialProofBar.tsx
import React from "react";

type SocialProofVariant = "industries" | "logos";

type LogoItem = {
  src: string;
  alt: string;
  href?: string;
};

type Props = {
  /**
   * Label shown above the items (e.g., "Industries we support", "Trusted by").
   * You can pass a translated string from your i18n layer.
   */
  label: string;

  /**
   * Render mode:
   * - "industries": renders keyword-rich chips (recommended if you don't have logo rights yet)
   * - "logos": renders a logo strip (requires `logos`)
   */
  variant?: SocialProofVariant;

  /** Industries keywords to display when variant = "industries" */
  industries?: string[];

  /** Logos to display when variant = "logos" */
  logos?: LogoItem[];

  /** Optional short line under the label */
  supportingText?: string;

  /** Tailwind overrides if needed */
  className?: string;
};

function cx(...parts: Array<string | undefined | false>) {
  return parts.filter(Boolean).join(" ");
}

export default function SocialProofBar({
  label,
  variant = "industries",
  industries = [
    "Restaurants & Hospitality",
    "E-commerce",
    "Property Management / Real Estate",
    "Clinics & Wellness",
    "Education & Training",
    "Events & Venues",
    "B2B Services",
  ],
  logos = [],
  supportingText,
  className,
}: Props) {
  const isLogos = variant === "logos" && logos.length > 0;

  return (
    <section
      aria-label="Social proof"
      className={styles.sectionWrapper}
    >
      <div className="mx-auto max-w-6xl">
        <div className="">
          <p className={styles.labelTitle}>
            {label}
          </p>
          {supportingText ? (
            <p className="text-md text-center my-4 sm:my-0">{supportingText}</p>
          ) : null}
        </div>

        {/* Content */}
        <div className="mt-4">
          {isLogos ? (
            <ul className="flex flex-wrap items-center justify-center gap-x-8 gap-y-4">
              {logos.map((logo, idx) => {
                const img = (
                  <img
                    src={logo.src}
                    alt={logo.alt}
                    loading="lazy"
                    className="h-8 w-auto opacity-70 grayscale transition-opacity duration-200 hover:opacity-100"
                  />
                );

                return (
                  <li key={`${logo.alt}-${idx}`} className="flex items-center">
                    {logo.href ? (
                      <a
                        href={logo.href}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="inline-flex items-center"
                        aria-label={logo.alt}
                      >
                        {img}
                      </a>
                    ) : (
                      img
                    )}
                  </li>
                );
              })}
            </ul>
          ) : (
            <ul className="flex flex-wrap justify-center gap-2">
              {industries.map((item) => (
                <li key={item}>
                  <span
                    className={cx(
                      "inline-flex items-center rounded-full",
                      "bg-secondary px-3 py-1",
                      "text-sm text-light shadow-sm",
                      "hover:border-secondary/20 hover:bg-secondary/80"
                    )}
                  >
                    {item}
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>
    </section>
  );
}

const styles = {
  sectionWrapper: "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
};