// src/components/MetricsStrip.tsx
import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";

type MetricItem = {
  /** Short headline (e.g., "Performance-first build") */
  title: string;
  /** 1–2 lines max recommended */
  description: string;
  /**
   * Optional highlight (e.g., "+42% leads", "Core Web Vitals", "WCAG")
   * If you don't have numeric metrics yet, use a keyword highlight.
   */
  highlight?: string;
  /**
   * Optional link to a service or case study
   * (e.g., "/en/services/performance/", "/en/work/chester-court/")
   */
  href?: string;
};

type Props = {
  /** Items to render (recommended: 3) */
  items: MetricItem[];

  /** Optional small label above the grid (e.g., "What we optimize") */
  label?: string;

  /** Tailwind overrides */
  className?: string;

  /**
   * Use a more compact layout (useful if placed right under SocialProofBar)
   */
  compact?: boolean;
};

function cx(...parts: Array<string | undefined | false>) {
  return parts.filter(Boolean).join(" ");
}

export default function MetricsStrip({
  items,
  label,
  className,
  compact = false,
}: Props) {
  if (!Array.isArray(items) || items.length === 0) return null;

  const { t } = useTranslation();
  return (
    <section
      aria-label="Key outcomes"
      className={styles.sectionWrapper}
    >
      <div
        className={cx(
          "mx-auto max-w-6xl px-4 sm:px-6",
          compact ? "py-6" : "py-10"
        )}
      >
        {label ? (
          <div className="text-center">
            <p className={styles.labelTitle}>
              {label}
            </p>
          </div>
        ) : null}

        <div className={cx("mt-4", compact ? "" : "mt-6")}>
          <ul className="grid grid-cols-1 gap-4 md:grid-cols-2">
            {items.slice(0, 6).map((m, idx) => {
              const CardInner = (
                <div
                  className={cx(
                    "h-full rounded-2xl border border-black/10 bg-secondary/70 p-5 shadow-sm",
                    "transition-transform duration-200",
                    m.href ? "hover:-translate-y-0.5 hover:border-black/20" : ""
                  )}
                >
                  {m.highlight ? (
                    <div className="mb-3">
                      <span
                        className={cx(
                          "inline-flex items-center rounded-full",
                          "border border-black/10 bg-primary px-2.5 py-1",
                          "text-xs font-medium text-light"
                        )}
                      >
                        {m.highlight}
                      </span>
                    </div>
                  ) : null}

                  <h3 className="text-base font-semibold text-light/90">
                    {m.title}
                  </h3>

                  <p className="mt-2 text-sm leading-relaxed text-light/70">
                    {m.description}
                  </p>

                  {m.href ? (
                    <p className="mt-4 text-sm font-medium text-light/80">
                      {t("servicesHub.learnMore")} <span aria-hidden="true">→</span>
                    </p>
                  ) : null}
                </div>
              );

              return (
                <li key={`${m.title}-${idx}`}>
                  {m.href ? (
                    <a
                      href={m.href}
                      className="block h-full"
                      aria-label={`${m.title} - learn more`}
                    >
                      {CardInner}
                    </a>
                  ) : (
                    CardInner
                  )}
                </li>
              );
            })}
          </ul>
        </div>
      </div>
    </section>
  );
}

const styles = {
  sectionWrapper: "border-2 w-full sm:w-[1024px] mx-auto rounded-xl p-2 sm:p-8 mt-8 bg-darkBg/50",
  labelTitle: "text-2xl sm:text-4xl text-center poppins-regular text-verde",
};